      original: "सशङ्खचक्रं सकिरीटकुण्डलं\nसपीतवस्त्रं सरसीरुहेक्षणम्।\nसहारवक्षःस्थलशोभिकौस्तुभं\nनमामि विष्णुं शिरसा चतुर्भुजम्॥",
