        od: "ସେ ଈଶ୍ୱର, ପରାକ୍ରମୀ, ଧନୁର୍ଧର, ମେଧାବୀ, ବିକ୍ରମଶାଳୀ ଏବଂ କ୍ରମବଦ୍ଧ। ସେ ଅନୁତ୍ତମ, ଦୁରାଧର୍ଷ, କୃତଜ୍ଞ, କୁଶଳ କର୍ତ୍ତା ଏବଂ ଆତ୍ମବାନ।",
