        od: "ସେ ଲୋକ, ଦେବତା ଓ ଧର୍ମର ଅଧ୍ୟକ୍ଷ, କର୍ମ ଓ କର୍ତ୍ତା ଉଭୟ ସ୍ୱରୂପ। ସେ ଚତୁରାତ୍ମା, ଚତୁର୍ବ୍ୟୂହ, ବରାହ ରୂପରେ ଚାରି ଦନ୍ତଧାରୀ ଏବଂ ଚତୁର୍ଭୁଜ।",
        te: "ఆయన లోకాలకు, దేవతలకు, ధర్మానికి అధ్యక్షుడు, కర్మ కర్త రెండూ ఆయనే. చతురాత్ముడు, చతుర్వ్యూహుడు, వరాహ రూపంలో నాలుగు దంష్ట్రలు గలవాడు, చతుర్భుజుడు.",
