        te: "ఆయన ప్రకాశించే భ్రాజిష్ణువు, భోజనమూ భోక్తా ఆయనే, సహనశీలి, జగత్తుకు ముందే ఉన్నవాడు. అనఘుడు అంటే పాపరహితుడు, విజయుడు, జేత, విశ్వయోని, పునర్వసువు, జీవుల్లో మళ్లీ మళ్లీ నివసించేవాడు.",
