        od: "ତାଙ୍କର ବୁଦ୍ଧି, ବୀର୍ଯ୍ୟ, ଶକ୍ତି ଓ ତେଜ ସବୁ ମହାନ୍। ତାଙ୍କ ରୂପକୁ ଆଙ୍ଗୁଳିରେ ଦେଖାଇ ହୁଏ ନାହିଁ, ସେ ଶ୍ରୀମାନ୍, ଅମେୟାତ୍ମା ଏବଂ ମହାଦ୍ରିଧୃକ୍, ଯେ ମହାନ ପର୍ବତ ଧାରଣ କରିଛନ୍ତି।",
