        od: "ସେ ସମସ୍ତ ସେନାର ଅଗ୍ରଣୀ ଅଗ୍ରଣୀ, ଶ୍ରୀମାନ୍, ନ୍ୟାୟ ସ୍ୱରୂପ, ପଥପ୍ରଦର୍ଶକ ନେତା ଏବଂ ସବୁକୁ ଗତିଶୀଳ କରୁଥିବା ସମୀରଣ। ତାଙ୍କର ସହସ୍ର ମସ୍ତକ, ଚକ୍ଷୁ ଓ ପାଦ, ସେ ବିଶ୍ୱାତ୍ମା।",
        te: "ఆయన సమూహాలన్నిటికీ ముందు నడిచే అగ్రణి, శ్రీమంతుడు, న్యాయ స్వరూపుడు, దారి చూపే నేత, అన్నిటినీ కదిలించే సమీరణుడు. ఆయనకు వేయి శిరస్సులు, కన్నులు, పాదాలు ఉన్నాయి, ఆయన విశ్వాత్మ.",
