        od: "ସେ ଜନ୍ମଚକ୍ର ଘୂରାଉଥିବା ଆବର୍ତ୍ତନ, କିନ୍ତୁ ତାଙ୍କ ଆତ୍ମା ସଂସାରରୁ ବିମୁଖ ନିବୃତ୍ତାତ୍ମା। ସେ ଆବୃତ କରନ୍ତି ଓ ଚୂର୍ଣ୍ଣ କରନ୍ତି। ସେ ଦିନର ଅନ୍ତକାରୀ, ଅଗ୍ନି ଓ ବାୟୁ ଏବଂ ପୃଥିବୀକୁ ଧାରଣ କରୁଥିବା ଧରଣୀଧର।",
        te: "ఆయన జన్మచక్రాన్ని తిప్పే ఆవర్తనుడు, కానీ ఆయన ఆత్మ సంసారం నుంచి మరలినది. ఆయన కప్పివేస్తాడు, నలిపివేస్తాడు. పగలును ముగించేవాడు, అగ్ని, వాయువు, భూమిని ధరించే ధరణీధరుడు.",
