        od: "ସେ ଅତି ପ୍ରସନ୍ନ ସୁପ୍ରସାଦ, ଶାନ୍ତ ସ୍ୱଭାବର ପ୍ରସନ୍ନାତ୍ମା, ବିଶ୍ୱର ଧାରକ ଓ ଭୋକ୍ତା ଏବଂ ସର୍ବବ୍ୟାପୀ ବିଭୁ। ସେ ସଜ୍ଜନଙ୍କୁ ସମ୍ମାନ ଦିଅନ୍ତି ଓ ସେମାନଙ୍କ ଦ୍ୱାରା ସମ୍ମାନିତ, ସାଧୁ, ଏବଂ ନାରାୟଣ ଓ ନର।",
