        od: "ସେ ଭୂତ, ଭବିଷ୍ୟ ଓ ବର୍ତ୍ତମାନର ନାଥ। ସେ ବାୟୁ, ପାବନକାରୀ ପବନ ଏବଂ ଅନଳ। ସେ କାମନା ହରଣ କରନ୍ତି ଓ ପୂରଣ ମଧ୍ୟ କରନ୍ତି, ସେ କାନ୍ତ ଓ କାମ, ବର ଦେଉଥିବା କାମପ୍ରଦ ଏବଂ ପ୍ରଭୁ।",
        te: "ఆయన గతం, వర్తమానం, భవిష్యత్తుకు నాథుడు. వాయువు, పవిత్రం చేసే పావనుడు, అగ్ని. కోరికలను హరించేవాడు, తీర్చేవాడు కూడా, అందమైనవాడు, ప్రియమైనవాడు, కోరికలను ఒసగే కామప్రదుడు, ప్రభువు.",
