        od: "ସେ କେବେ ନିରାଶ ହୁଅନ୍ତି ନାହିଁ ଅନିର୍ବିଣ୍ଣ, ଆକାରରେ ସର୍ବଶ୍ରେଷ୍ଠ ସ୍ଥବିଷ୍ଠ, ଜନ୍ମରହିତ ଅଭୂ ଏବଂ ଯଜ୍ଞରେ ଧର୍ମର ଯୂପ। ସେ ମହାଯଜ୍ଞ ମହାମଖ, ନକ୍ଷତ୍ରମାନଙ୍କ ନାଭି ନକ୍ଷତ୍ରନେମି ଓ ସେମାନଙ୍କ ପତି ନକ୍ଷତ୍ରୀ, କ୍ଷମାଶୀଳ କ୍ଷମ ଓ ସଦା କର୍ମରତ ସମୀହନ।",
        te: "ఆయన ఎన్నడూ నిరాశ చెందని అనిర్విణ్ణుడు, పరిమాణంలో అతి పెద్దవాడు, పుట్టుక లేనివాడు, యజ్ఞంలో ధర్మానికి యూపస్తంభం. మహాయజ్ఞమైన మహామఖుడు, నక్షత్రాలకు కేంద్రమైన నక్షత్రనేమి, వాటి ప్రభువు నక్షత్రి, సహనశీలుడైన క్షముడు, ఎప్పుడూ కర్మ నిరతుడైన సమీహనుడు.",
