      original: "यज्ञ इज्यो महेज्यश्च क्रतुः सत्रं सतां गतिः।\nसर्वदर्शी विमुक्तात्मा सर्वज्ञो ज्ञानमुत्तमम्॥",
      script: {
        od: "ୟଜ୍ଞ ଇଜ୍ୟୋ ମହେଜ୍ୟଶ୍ଚ କ୍ରତୁଃ ସତ୍ରଂ ସତାଂ ଗତିଃ।\nସର୍ବଦର୍ଶୀ ବିମୁକ୍ତାତ୍ମା ସର୍ବଜ୍ଞୋ ଜ୍ଞାନମୁତ୍ତମମ୍॥",
        te: "యజ్ఞ ఇజ్యో మహేజ్యశ్చ క్రతుః సత్రం సతాం గతిః।\nసర్వదర్శీ విముక్తాత్మా సర్వజ్ఞో జ్ఞానముత్తమమ్॥",
      },
      meaning: {
        en: "He is the sacrifice itself, worthy of worship and greatest to be worshipped, the rite and the long sacrifice, and the refuge of the good. He sees all, is ever free, all-knowing, and the highest knowledge.",
        hi: "वे स्वयं यज्ञ हैं, पूज्य और सबसे पूज्य, क्रतु और दीर्घ यज्ञ, और सज्जनों की गति। वे सब देखते हैं, सदा मुक्त, सर्वज्ञ और परम ज्ञान हैं।",
        od: "ସେ ଯଜ୍ଞ ସ୍ୱୟଂ, ପୂଜ୍ୟ ଇଜ୍ୟ ଏବଂ ସର୍ବଶ୍ରେଷ୍ଠ ପୂଜ୍ୟ ମହେଜ୍ୟ, କ୍ରତୁ ଓ ଦୀର୍ଘ ଯଜ୍ଞ ସତ୍ର, ଏବଂ ସଜ୍ଜନଙ୍କ ଆଶ୍ରୟ। ସେ ସର୍ବଦର୍ଶୀ, ସଦା ମୁକ୍ତ ବିମୁକ୍ତାତ୍ମା, ସର୍ବଜ୍ଞ ଏବଂ ସର୍ବୋତ୍ତମ ଜ୍ଞାନ।",
        te: "ఆయనే యజ్ఞం, పూజింపదగిన ఇజ్యుడు, అందరికంటే ఎక్కువగా పూజించదగిన మహేజ్యుడు, క్రతువు, దీర్ఘ యజ్ఞమైన సత్రం, సజ్జనులకు ఆశ్రయం. అన్నీ చూసేవాడు, సదా విముక్తుడు, సర్వజ్ఞుడు, ఉత్తమమైన జ్ఞానం.",
      },
