        od: "ତାଙ୍କ ବ୍ରତ ଉତ୍ତମ ସୁବ୍ରତ, ମୁଖ ସୁନ୍ଦର ସୁମୁଖ, ସେ ସୂକ୍ଷ୍ମ ଓ ମଙ୍ଗଳମୟ ସ୍ୱର ଥିବା ସୁଘୋଷ। ସେ ସୁଖଦାତା, ପ୍ରକୃତ ବନ୍ଧୁ ସୁହୃତ୍, ମନୋହର, କ୍ରୋଧଜୟୀ, ମହାବାହୁ ବୀରବାହୁ ଏବଂ ଅଧର୍ମକୁ ବିଦାରଣ କରୁଥିବା ବିଦାରଣ।",
