        od: "ସେ ମହାବରାହ ଓ ଗୋବିନ୍ଦ, ଉତ୍ତମ ସେନାଯୁକ୍ତ ସୁଷେଣ ଏବଂ ସୁବର୍ଣ୍ଣ ବାଜୁବନ୍ଧଧାରୀ କନକାଙ୍ଗଦୀ। ସେ ଗୁହ୍ୟ ରହସ୍ୟ, ଗମ୍ଭୀର, ଗହନ, ଗୁପ୍ତ, ଏବଂ ଚକ୍ର ଓ ଗଦା ଧାରଣକାରୀ ଚକ୍ରଗଦାଧର।",
        te: "ఆయన మహావరాహుడు, గోవిందుడు, చక్కని సైన్యం గల సుషేణుడు, బంగారు భుజకీర్తులు ధరించే కనకాంగది. గుహ్యుడు అంటే రహస్యం, గంభీరుడు, అగాధుడు, గుప్తుడు, చక్రాన్ని, గదను ధరించే చక్రగదాధరుడు.",
