        od: "ତାଙ୍କ ଅଙ୍ଗ ସୁନ୍ଦର ଶୁଭାଙ୍ଗ ଓ ସେ ଶାନ୍ତି ଦିଅନ୍ତି ଶାନ୍ତିଦ। ସେ ସ୍ରଷ୍ଟା, ପୃଥିବୀରେ ଆନନ୍ଦ ପାଉଥିବା କୁମୁଦ ଏବଂ ଜଳରେ ଶୟନ କରୁଥିବା କୁବଳେଶୟ। ସେ ଗୋହିତ, ଗୋପତି, ଗୋପ୍ତା, ବୃଷଭାକ୍ଷ ଏବଂ ଧର୍ମପ୍ରିୟ ବୃଷପ୍ରିୟ।",
        te: "ఆయన అవయవాలు సుందరమైనవి, శాంతిని ఇచ్చేవాడు. సృష్టికర్త, భూమిపై ఆనందించే కుముదుడు, జలాలపై శయనించే కువలేశయుడు. గోవులకు మేలు చేసేవాడు, గోపతి, రక్షకుడు, వృషభం వంటి కన్నులు గలవాడు, ధర్మప్రియుడు.",
