      original: "श्रीदः श्रीशः श्रीनिवासः श्रीनिधिः श्रीविभावनः।\nश्रीधरः श्रीकरः श्रेयः श्रीमाँल्लोकत्रयाश्रयः॥",
      script: {
        od: "ଶ୍ରୀଦଃ ଶ୍ରୀଶଃ ଶ୍ରୀନିବାସଃ ଶ୍ରୀନିଧିଃ ଶ୍ରୀବିଭାବନଃ।\nଶ୍ରୀଧରଃ ଶ୍ରୀକରଃ ଶ୍ରେୟଃ ଶ୍ରୀମାଁଲ୍ଲୋକତ୍ରୟାଶ୍ରୟଃ॥",
        te: "శ్రీదః శ్రీశః శ్రీనివాసః శ్రీనిధిః శ్రీవిభావనః।\nశ్రీధరః శ్రీకరః శ్రేయః శ్రీమాంల్లోకత్రయాశ్రయః॥",
      },
      meaning: {
        en: "He gives, rules and houses Shri, is her treasury, and shares her out. He bears Shri and makes it. He is the highest good, glorious, and the refuge of the three worlds.",
        hi: "वे श्री देते हैं, उस पर शासन करते हैं और उसे धारण करते हैं, उसके कोष हैं और उसका बँटवारा करते हैं। वे श्री धारण करते और रचते हैं। वे परम कल्याण हैं, श्रीमान और तीनों लोकों के आश्रय।",
        od: "ସେ ଶ୍ରୀ ଦିଅନ୍ତି ଶ୍ରୀଦ, ଶ୍ରୀଙ୍କ ଈଶ ଶ୍ରୀଶ, ଶ୍ରୀଙ୍କ ନିବାସ ଶ୍ରୀନିବାସ, ଶ୍ରୀଙ୍କ ନିଧି ଶ୍ରୀନିଧି ଏବଂ ଶ୍ରୀକୁ ବାଣ୍ଟୁଥିବା ଶ୍ରୀବିଭାବନ। ସେ ଶ୍ରୀଧର, ଶ୍ରୀକର, ପରମ କଲ୍ୟାଣ ଶ୍ରେୟ, ଶ୍ରୀମାନ୍ ଏବଂ ତିନି ଲୋକର ଆଶ୍ରୟ।",
        te: "ఆయన శ్రీని ఇచ్చే శ్రీదుడు, శ్రీకి ఈశుడు శ్రీశుడు, శ్రీ నివసించే శ్రీనివాసుడు, శ్రీకి నిధి శ్రీనిధి, శ్రీని పంచేవాడు శ్రీవిభావనుడు. శ్రీధరుడు, శ్రీకరుడు, పరమ శ్రేయస్సు, శ్రీమంతుడు, మూడు లోకాలకు ఆశ్రయం.",
      },
