        od: "ସେ ସ୍ତୁତିଯୋଗ୍ୟ ସ୍ତବ୍ୟ ଓ ସ୍ତୁତିପ୍ରିୟ ସ୍ତବପ୍ରିୟ, ସ୍ତୋତ୍ର, ସ୍ତୁତି ଏବଂ ସ୍ତୋତା। ସେ ରଣପ୍ରିୟ, ପୂର୍ଣ୍ଣ, ପୂରଣକାରୀ ପୂରୟିତା, ପୁଣ୍ୟ, ପୁଣ୍ୟକୀର୍ତ୍ତି ଏବଂ ଅନାମୟ, ଯାହାଙ୍କଠାରେ ରୋଗ ନାହିଁ।",
        te: "ఆయన స్తుతింపదగినవాడు, స్తుతిని ప్రేమించేవాడు, స్తోత్రం, స్తుతి, స్తుతించేవాడు కూడా. రణాన్ని ఇష్టపడే రణప్రియుడు, పూర్ణుడు, నింపే పూరయితా, పుణ్యుడు, పుణ్య కీర్తి గలవాడు, అనామయుడు.",
