      original: "मनोजवस्तीर्थकरो वसुरेता वसुप्रदः।\nवसुप्रदो वासुदेवो वसुर्वसुमना हविः॥",
      script: {
        od: "ମନୋଜବସ୍ତୀର୍ଥକରୋ ବସୁରେତା ବସୁପ୍ରଦଃ।\nବସୁପ୍ରଦୋ ବାସୁଦେବୋ ବସୁର୍ବସୁମନା ହବିଃ॥",
        te: "మనోజవస్తీర్థకరో వసురేతా వసుప్రదః।\nవసుప్రదో వాసుదేవో వసుర్వసుమనా హవిః॥",
      },
      meaning: {
        en: "He is swift as the mind and the maker of sacred fords, of golden seed, and the giver of wealth. He is Vasudeva and wealth himself, generous-minded, and the offering.",
        hi: "वे मन के समान वेग वाले हैं और तीर्थों के रचयिता, स्वर्ण-बीज वाले और धन देने वाले। वे वासुदेव और स्वयं धन हैं, उदार मन वाले और हवि।",
        od: "ସେ ମନ ପରି ବେଗବାନ ମନୋଜବ, ତୀର୍ଥ ସୃଷ୍ଟିକାରୀ ତୀର୍ଥକର, ସୁବର୍ଣ୍ଣ ବୀଜ ବସୁରେତା ଏବଂ ଧନଦାତା ବସୁପ୍ରଦ। ସେ ବାସୁଦେବ ଓ ବସୁ ସ୍ୱୟଂ, ଉଦାର ମନଯୁକ୍ତ ବସୁମନା ଏବଂ ହବି।",
        te: "ఆయన మనసు వేగం గల మనోజవుడు, పవిత్ర తీర్థాలను సృష్టించే తీర్థకరుడు, బంగారు బీజం గల వసురేతుడు, ధనాన్ని ఇచ్చే వసుప్రదుడు. వాసుదేవుడు, వసువు ఆయనే, ఉదార మనస్కుడైన వసుమనుడు, హవిస్సు.",
      },
