      original: "समावर्तोऽनिवृत्तात्मा दुर्जयो दुरतिक्रमः।\nदुर्लभो दुर्गमो दुर्गो दुरावासो दुरारिहा॥",
      script: {
        od: "ସମାବର୍ତୋଽନିବୃତ୍ତାତ୍ମା ଦୁର୍ଜୟୋ ଦୁରତିକ୍ରମଃ।\nଦୁର୍ଲଭୋ ଦୁର୍ଗମୋ ଦୁର୍ଗୋ ଦୁରାବାସୋ ଦୁରାରିହା॥",
        te: "సమావర్తోఽనివృత్తాత్మా దుర్జయో దురతిక్రమః।\nదుర్లభో దుర్గమో దుర్గో దురావాసో దురారిహా॥",
      },
      meaning: {
        en: "He turns back and yet his Self never turns from the truth. He is hard to conquer and hard to cross, hard to attain and reach. He is a fortress, hard to find as a home, and slays foes.",
        hi: "वे लौटते हैं, फिर भी उनकी आत्मा सत्य से कभी नहीं हटती। वे जीतने में कठिन और पार करने में कठिन हैं, पाने और पहुँचने में कठिन। वे दुर्ग हैं, निवास के रूप में खोजने में कठिन, और शत्रुओं के संहारक।",
        od: "ସେ ଫେରିଆସନ୍ତି ସମାବର୍ତ୍ତ, ତଥାପି ତାଙ୍କ ଆତ୍ମା ସତ୍ୟରୁ କେବେ ବିମୁଖ ହୁଏ ନାହିଁ ଅନିବୃତ୍ତାତ୍ମା। ସେ ଜିତିବା କଷ୍ଟ ଦୁର୍ଜୟ, ପାର ହେବା କଷ୍ଟ ଦୁରତିକ୍ରମ, ପାଇବା କଷ୍ଟ ଦୁର୍ଲଭ, ପହଞ୍ଚିବା କଷ୍ଟ ଦୁର୍ଗମ। ସେ ଦୁର୍ଗ, ବାସ କରିବା କଷ୍ଟ ଦୁରାବାସ ଏବଂ ଶତ୍ରୁହନ୍ତା ଦୁରାରିହା।",
        te: "ఆయన తిరిగి వచ్చే సమావర్తుడు, అయినా ఆయన ఆత్మ సత్యం నుంచి ఎన్నడూ తొలగదు, అనివృత్తాత్ముడు. జయించడం కష్టమైన దుర్జయుడు, దాటడం కష్టమైన దురతిక్రముడు, పొందడం కష్టమైన దుర్లభుడు, చేరడం కష్టమైన దుర్గముడు. ఆయన దుర్గం, నివసించడం కష్టమైన దురావాసుడు, శత్రువులను సంహరించే దురారిహుడు.",
      },
