        od: "ତାଙ୍କ ଅଙ୍ଗ ସୁନ୍ଦର ଶୁଭାଙ୍ଗ ଓ ସେ ଲୋକମାନଙ୍କ ସାର ଲୋକସାରଙ୍ଗ। ସେ ସୁନ୍ଦର ସୂତା ସୁତନ୍ତୁ ଓ ତାକୁ ବିସ୍ତାରକାରୀ ତନ୍ତୁବର୍ଦ୍ଧନ। ସେ ଇନ୍ଦ୍ରକର୍ମା ଅର୍ଥାତ୍ ଇନ୍ଦ୍ର ସମ କର୍ମକାରୀ, ମହାକର୍ମା, କୃତକର୍ମା ଯାହାଙ୍କ କାର୍ଯ୍ୟ ସମାପ୍ତ, ଏବଂ ପବିତ୍ର ପରମ୍ପରାର ରଚୟିତା କୃତାଗମ।",
        te: "ఆయన అవయవాలు అందమైనవి, లోకాల సారం లోకసారంగుడు. చక్కని దారం సుతంతువు, దాన్ని విస్తరించే తంతువర్ధనుడు. ఇంద్రునిలా కర్మలు చేసే ఇంద్రకర్ముడు, మహాకర్ముడు, చేయవలసిన పని పూర్తి చేసిన కృతకర్ముడు, పవిత్ర సంప్రదాయాన్ని రూపొందించిన కృతాగముడు.",
