        od: "ସେ ଅନନ୍ତ ଓ ହବି ଭୋକ୍ତା ହୁତଭୁକ୍, ସୁଖଦାତା ସୁଖଦ, ଅନେକ ଭାବେ ଜାତ ନୈକଜ ଏବଂ ପ୍ରଥମଜାତ ଅଗ୍ରଜ। ସେ କେବେ ନିରାଶ ହୁଅନ୍ତି ନାହିଁ ଅନିର୍ବିଣ୍ଣ, ସଦା କ୍ଷମାଶୀଳ ସଦାମର୍ଷୀ, ଲୋକମାନଙ୍କ ଆଧାର ଲୋକାଧିଷ୍ଠାନ ଏବଂ ଅଦ୍ଭୁତ।",
