        od: "ସେ ସନାତନ ଓ ସର୍ବାଧିକ ପ୍ରାଚୀନ ସନତ୍ ସନାତନତମ, ମହର୍ଷି କପିଳ ଏବଂ ଅବ୍ୟୟ କପି। ସେ ମଙ୍ଗଳ ଦିଅନ୍ତି ସ୍ୱସ୍ତିଦ, କରନ୍ତି ସ୍ୱସ୍ତିକୃତ୍, ସ୍ୱୟଂ ସ୍ୱସ୍ତି, ତାହା ଭୋଗ କରନ୍ତି ସ୍ୱସ୍ତିଭୁକ୍ ଏବଂ ଉଦାର ଭାବେ ବିତରଣ କରନ୍ତି ସ୍ୱସ୍ତିଦକ୍ଷିଣ।",
        te: "ఆయన శాశ్వతుడు, అత్యంత ప్రాచీనుడు, మహర్షి కపిలుడు, నాశనం లేని కపి. శుభాన్ని ఇచ్చే స్వస్తిదుడు, చేసే స్వస్తికృత్, శుభమే ఆయన స్వస్తి, దాన్ని అనుభవించే స్వస్తిభుక్, ఉదారంగా పంచే స్వస్తిదక్షిణుడు.",
