        od: "ସେ ଉଗ୍ର ନୁହନ୍ତି ଅରୌଦ୍ର, କୁଣ୍ଡଳଧାରୀ କୁଣ୍ଡଳୀ, ଚକ୍ରଧାରୀ ଚକ୍ରୀ ଓ ପରାକ୍ରମୀ ବିକ୍ରମୀ, ମହାନ ଆଜ୍ଞା ଥିବା ଊର୍ଜିତଶାସନ। ସେ ଶବ୍ଦାତୀତ ଶବ୍ଦାତିଗ, ଶବ୍ଦ ସହନକାରୀ ଶବ୍ଦସହ, ଶୀତଳ ଶିଶିର ଏବଂ ରାତ୍ରି ସୃଷ୍ଟିକାରୀ ଶର୍ବରୀକର।",
        te: "ఆయన ఉగ్రుడు కాని అరౌద్రుడు, కుండలాలు ధరించే కుండలి, చక్రం ధరించే చక్రి, పరాక్రమశాలి, గొప్ప ఆజ్ఞ గల ఊర్జితశాసనుడు. మాటలకు అతీతుడు, శబ్దాన్ని సహించేవాడు, చల్లనివాడైన శిశిరుడు, రాత్రిని కలిగించే శర్వరీకరుడు.",
