        od: "ସେ ପ୍ରମାଣ ଏବଂ ପ୍ରାଣର ନିବାସ ପ୍ରାଣନିଳୟ, ପ୍ରାଣଧାରକ ପ୍ରାଣଭୃତ୍ ଓ ପ୍ରାଣର ପ୍ରାଣ ପ୍ରାଣଜୀବନ। ସେ ତତ୍ତ୍ୱ ଓ ତତ୍ତ୍ୱଜ୍ଞ, ଏକମାତ୍ର ଆତ୍ମା ଏକାତ୍ମା, ଏବଂ ଜନ୍ମ, ମୃତ୍ୟୁ ଓ ଜରାକୁ ଅତିକ୍ରମ କରିଥିବା ଜନ୍ମମୃତ୍ୟୁଜରାତିଗ।",
        te: "ఆయన ప్రమాణం, ప్రాణాలకు నిలయమైన ప్రాణనిలయుడు, ప్రాణాలను భరించే ప్రాణభృత్, ప్రాణానికే ప్రాణమైన ప్రాణజీవనుడు. తత్త్వం, తత్త్వం తెలిసినవాడు, ఏకైక ఆత్మ అయిన ఏకాత్ముడు, పుట్టుక, మరణం, ముసలితనాన్ని దాటిన జన్మమృత్యుజరాతిగుడు.",
